  1→import { useState, useCallback, useMemo, useEffect, useRef } from "react";
  2→import type {
  3→  ActionFunctionArgs,
  4→  HeadersFunction,
  5→  LoaderFunctionArgs,
  6→} from "react-router";
  7→import { useFetcher, useLoaderData, useNavigate, useRouteError } from "react-router";
  8→import { useAppBridge } from "@shopify/app-bridge-react";
  9→import { authenticate } from "../shopify.server";
 10→import { boundary } from "@shopify/shopify-app-react-router/server";
 11→import db from "../db.server";
 12→import {
 13→  Page,
 14→  Layout,
 15→  Card,
 16→  BlockStack,
 17→  InlineStack,
 18→  Text,
 19→  Button,
 20→  TextField,
 21→  Select,
 22→  Modal,
 23→  EmptyState,
 24→  Divider,
 25→  Box,
 26→  Badge,
 27→  Tabs,
 28→  InlineGrid,
 29→  Banner,
 30→} from "@shopify/polaris";
 31→import { PlusIcon, DeleteIcon, ChevronUpIcon } from "@shopify/polaris-icons";
 32→
 33→const PAGE_SIZE = 10;
 34→
 35→// ---------------------------------------------------------------------------
 36→// Types
 37→// ---------------------------------------------------------------------------
 38→
 39→type FeatureRequestRecord = {
 40→  id: string;
 41→  title: string;
 42→  description: string;
 43→  category: string;
 44→  status: string;
 45→  shop: string;
 46→  votesCount: number;
 47→  createdAt: string | Date;
 48→  updatedAt: string | Date;
 49→};
 50→
 51→type ActionResult =
 52→  | { success: true; intent: string; featureId?: string; newCount?: number; voted?: boolean }
 53→  | { error: string };
 54→
 55→// ---------------------------------------------------------------------------
 56→// Loader
 57→// ---------------------------------------------------------------------------
 58→
 59→export const loader = async ({ request }: LoaderFunctionArgs) => {
 60→  const { session } = await authenticate.admin(request);
 61→  const shop = session.shop;
 62→
 63→  const [features, myVotes] = await Promise.all([
 64→    db.featureRequest.findMany({
 65→      orderBy: { votesCount: "desc" },
 66→    }),
 67→    db.featureVote.findMany({
 68→      where: { shop },
 69→      select: { featureRequestId: true },
 70→    }),
 71→  ]);
 72→
 73→  const votedIds = myVotes.map((v) => v.featureRequestId);
 74→
 75→  const stats = {
 76→    total: features.length,
 77→    under_review: features.filter((f) => f.status === "under_review").length,
 78→    planned: features.filter((f) => f.status === "planned").length,
 79→    in_progress: features.filter((f) => f.status === "in_progress").length,
 80→    done: features.filter(
 81→      (f) => f.status === "done" || f.status === "shipped",
 82→    ).length,
 83→  };
 84→
 85→  return { features, votedIds, shop, stats };
 86→};
 87→
 88→// ---------------------------------------------------------------------------
 89→// Action
 90→// ---------------------------------------------------------------------------
 91→
 92→export const action = async ({
 93→  request,
 94→}: ActionFunctionArgs): Promise<ActionResult> => {
 95→  const { session } = await authenticate.admin(request);
 96→  const shop = session.shop;
 97→  const formData = await request.formData();
 98→  const intent = String(formData.get("intent") ?? "");
 99→
100→  try {
101→    switch (intent) {
102→      case "submit": {
103→        const title = String(formData.get("title") ?? "").trim();
104→        const description = String(formData.get("description") ?? "").trim();
105→        const category = String(formData.get("category") ?? "General").trim();
106→
107→        if (!title || !description) {
108→          return { error: "Title and description are required." };
109→        }
110→        if (title.length > 150) {
111→          return { error: "Title must be 150 characters or fewer." };
112→        }
113→
114→        await db.featureRequest.create({
115→          data: { title, description, category, shop },
116→        });
117→
118→        return { success: true, intent: "submit" };
119→      }
120→
121→      case "vote": {
122→        const featureId = String(formData.get("featureId") ?? "").trim();
123→        if (!featureId) return { error: "Feature ID is required." };
124→
125→        const feature = await db.featureRequest.findUnique({
126→          where: { id: featureId },
127→        });
128→        if (!feature) return { error: "Feature request not found." };
129→
130→        const existing = await db.featureVote.findUnique({
131→          where: {
132→            featureRequestId_shop: { featureRequestId: featureId, shop },
133→          },
134→        });
135→
136→        let newCount: number;
137→        let voted: boolean;
138→
139→        if (existing) {
140→          await db.featureVote.delete({ where: { id: existing.id } });
141→          newCount = Math.max(0, feature.votesCount - 1);
142→          await db.featureRequest.update({
143→            where: { id: featureId },
144→            data: { votesCount: newCount },
145→          });
146→          voted = false;
147→        } else {
148→          await db.featureVote.create({
149→            data: { featureRequestId: featureId, shop },
150→          });
151→          newCount = feature.votesCount + 1;
152→          await db.featureRequest.update({
153→            where: { id: featureId },
154→            data: { votesCount: newCount },
155→          });
156→          voted = true;
157→        }
158→
159→        return { success: true, intent: "vote", featureId, newCount, voted };
160→      }
161→
162→      case "delete": {
163→        const deleteId = String(formData.get("id") ?? "").trim();
164→        if (!deleteId) return { error: "Feature ID is required." };
165→
166→        const toDelete = await db.featureRequest.findUnique({
167→          where: { id: deleteId },
168→        });
169→        if (!toDelete) return { error: "Feature request not found." };
170→        if (toDelete.shop !== shop) {
171→          return { error: "You can only delete your own feature requests." };
172→        }
173→
174→        await db.featureRequest.delete({ where: { id: deleteId } });
175→        return { success: true, intent: "delete" };
176→      }
177→
178→      default:
179→        return { error: "Unknown action." };
180→    }
181→  } catch (err) {
182→    const message =
183→      err instanceof Error ? err.message : "An unexpected error occurred.";
184→    return { error: message };
185→  }
186→};
187→
188→// ---------------------------------------------------------------------------
189→// Helpers
190→// ---------------------------------------------------------------------------
191→
192→const STATUS_LABELS: Record<string, string> = {
193→  under_review: "Under Review",
194→  planned: "Planned",
195→  in_progress: "In Progress",
196→  done: "Done",
197→  shipped: "Shipped",
198→};
199→
200→type BadgeTone =
201→  | "attention"
202→  | "info"
203→  | "warning"
204→  | "success"
205→  | "critical"
206→  | undefined;
207→
208→const STATUS_TONES: Record<string, BadgeTone> = {
209→  under_review: "attention",
210→  planned: "info",
211→  in_progress: "warning",
212→  done: "success",
213→  shipped: "success",
214→};
215→
216→const CATEGORY_OPTIONS = [
217→  { label: "General", value: "General" },
218→  { label: "UI & Design", value: "UI & Design" },
219→  { label: "Data & Export", value: "Data & Export" },
220→  { label: "API & Integration", value: "API & Integration" },
221→  { label: "Performance", value: "Performance" },
222→  { label: "Billing", value: "Billing" },
223→];
224→
225→const TAB_FILTERS = [
226→  "all",
227→  "under_review",
228→  "planned",
229→  "in_progress",
230→  "done",
231→] as const;
232→type TabFilter = (typeof TAB_FILTERS)[number];
233→
234→const SORT_OPTIONS = [
235→  { label: "Most Voted", value: "votes" },
236→  { label: "Newest", value: "newest" },
237→  { label: "Oldest", value: "oldest" },
238→];
239→
240→function formatDate(d: string | Date): string {
241→  return new Date(d).toLocaleDateString("en-US", {
242→    month: "short",
243→    day: "numeric",
244→    year: "numeric",
245→  });
246→}
247→
248→function truncateText(text: string, maxChars: number): string {
249→  if (text.length <= maxChars) return text;
250→  return text.slice(0, maxChars).trimEnd() + "\u2026";
251→}
252→
253→// ---------------------------------------------------------------------------
254→// Component
255→// ---------------------------------------------------------------------------
256→
257→export default function FeatureRequestsPage() {
258→  const {
259→    features: rawFeatures,
260→    votedIds: initialVotedIds,
261→    shop,
262→    stats,
263→  } = useLoaderData<typeof loader>();
264→
265→  const fetcher = useFetcher<typeof action>();
266→  const shopify = useAppBridge();
267→  const navigate = useNavigate();
268→
269→  // Track the pending operation details so we can use them inside useEffect
270→  // without relying on fetcher.formData (which has a narrow type in generics)
271→  const pendingIntentRef = useRef<string | null>(null);
272→  const pendingFeatureIdRef = useRef<string | null>(null);
273→  const pendingDeleteIdRef = useRef<string | null>(null);
274→
275→  // ------------------------------------------------------------------
276→  // Local state — optimistic votes
277→  // ------------------------------------------------------------------
278→  const [optimisticVotes, setOptimisticVotes] = useState<
279→    Map<string, { count: number; voted: boolean }>
280→  >(() => new Map());
281→  const [votedIds, setVotedIds] = useState<Set<string>>(
282→    () => new Set(initialVotedIds),
283→  );
284→
285→  // Per-card loading indicators
286→  const [pendingVoteId, setPendingVoteId] = useState<string | null>(null);
287→  const [pendingDeleteId, setPendingDeleteId] = useState<string | null>(null);
288→  const [isSubmitting, setIsSubmitting] = useState(false);
289→
290→  // ------------------------------------------------------------------
291→  // UI state
292→  // ------------------------------------------------------------------
293→  const [selectedTab, setSelectedTab] = useState(0);
294→  const [sortValue, setSortValue] = useState("votes");
295→  const [currentPage, setCurrentPage] = useState(1);
296→  const [modalOpen, setModalOpen] = useState(false);
297→  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
298→  const [modalError, setModalError] = useState<string | null>(null);
299→
300→  // Form state
301→  const [newTitle, setNewTitle] = useState("");
302→  const [newDescription, setNewDescription] = useState("");
303→  const [newCategory, setNewCategory] = useState("General");
304→
305→  // ------------------------------------------------------------------
306→  // Resolve optimistic state into features list
307→  // ------------------------------------------------------------------
308→  const features = useMemo<FeatureRequestRecord[]>(() => {
309→    return (rawFeatures as FeatureRequestRecord[]).map((f) => {
310→      const opt = optimisticVotes.get(f.id);
311→      if (opt) return { ...f, votesCount: opt.count };
312→      return f;
313→    });
314→  }, [rawFeatures, optimisticVotes]);
315→
316→  // ------------------------------------------------------------------
317→  // Handle fetcher responses
318→  // ------------------------------------------------------------------
319→  useEffect(() => {
320→    if (fetcher.state !== "idle" || !fetcher.data) return;
321→
322→    const data = fetcher.data;
323→    const lastIntent = pendingIntentRef.current;
324→
325→    if ("error" in data) {
326→      if (lastIntent === "submit") {
327→        setModalError(data.error);
328→      } else {
329→        shopify.toast.show(data.error, { isError: true });
330→      }
331→      setPendingVoteId(null);
332→      setPendingDeleteId(null);
333→      setIsSubmitting(false);
334→      return;
335→    }
336→
337→    if ("success" in data && data.success) {
338→      if (data.intent === "submit") {
339→        shopify.toast.show("Feature request submitted! Thank you.");
340→        setModalOpen(false);
341→        setNewTitle("");
342→        setNewDescription("");
343→        setNewCategory("General");
344→        setModalError(null);
345→        setIsSubmitting(false);
346→      } else if (data.intent === "vote") {
347→        const fid = data.featureId;
348→        if (fid !== undefined) {
349→          setOptimisticVotes((prev) => {
350→            const next = new Map(prev);
351→            if (data.newCount !== undefined) {
352→              next.set(fid, {
353→                count: data.newCount,
354→                voted: data.voted ?? false,
355→              });
356→            }
357→            return next;
358→          });
359→          setVotedIds((prev) => {
360→            const next = new Set(prev);
361→            if (data.voted) next.add(fid);
362→            else next.delete(fid);
363→            return next;
364→          });
365→        }
366→        setPendingVoteId(null);
367→      } else if (data.intent === "delete") {
368→        shopify.toast.show("Feature request deleted.");
369→        setPendingDeleteId(null);
370→      }
371→    }
372→  }, [fetcher.state, fetcher.data, shopify]);
373→
374→  // ------------------------------------------------------------------
375→  // Filter + sort
376→  // ------------------------------------------------------------------
377→  const tabFilter: TabFilter = TAB_FILTERS[selectedTab] ?? "all";
378→
379→  const filteredFeatures = useMemo(() => {
380→    let list = features;
381→
382→    if (tabFilter !== "all") {
383→      if (tabFilter === "done") {
384→        list = list.filter(
385→          (f) => f.status === "done" || f.status === "shipped",
386→        );
387→      } else {
388→        list = list.filter((f) => f.status === tabFilter);
389→      }
390→    }
391→
392→    return [...list].sort((a, b) => {
393→      if (sortValue === "votes") return b.votesCount - a.votesCount;
394→      if (sortValue === "newest")
395→        return (
396→          new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
397→        );
398→      if (sortValue === "oldest")
399→        return (
400→          new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
401→        );
402→      return 0;
403→    });
404→  }, [features, tabFilter, sortValue]);
405→
406→  const totalPages = Math.max(
407→    1,
408→    Math.ceil(filteredFeatures.length / PAGE_SIZE),
409→  );
410→  const paginatedFeatures = useMemo(() => {
411→    const start = (currentPage - 1) * PAGE_SIZE;
412→    return filteredFeatures.slice(start, start + PAGE_SIZE);
413→  }, [filteredFeatures, currentPage]);
414→
415→  // ------------------------------------------------------------------
416→  // Handlers
417→  // ------------------------------------------------------------------
418→  const handleTabChange = useCallback((tabIndex: number) => {
419→    setSelectedTab(tabIndex);
420→    setCurrentPage(1);
421→  }, []);
422→
423→  const handleSortChange = useCallback((val: string) => {
424→    setSortValue(val);
425→    setCurrentPage(1);
426→  }, []);
427→
428→  const handleVote = useCallback(
429→    (featureId: string) => {
430→      const feature = features.find((f) => f.id === featureId);
431→      if (!feature) return;
432→
433→      const currentlyVoted = votedIds.has(featureId);
434→      const currentCount =
435→        optimisticVotes.get(featureId)?.count ?? feature.votesCount;
436→
437→      // Optimistic update
438→      setOptimisticVotes((prev) => {
439→        const next = new Map(prev);
440→        next.set(featureId, {
441→          count: currentlyVoted
442→            ? Math.max(0, currentCount - 1)
443→            : currentCount + 1,
444→          voted: !currentlyVoted,
445→        });
446→        return next;
447→      });
448→      setVotedIds((prev) => {
449→        const next = new Set(prev);
450→        if (currentlyVoted) next.delete(featureId);
451→        else next.add(featureId);
452→        return next;
453→      });
454→
455→      pendingIntentRef.current = "vote";
456→      pendingFeatureIdRef.current = featureId;
457→      setPendingVoteId(featureId);
458→
459→      const fd = new FormData();
460→      fd.set("intent", "vote");
461→      fd.set("featureId", featureId);
462→      fetcher.submit(fd, { method: "POST" });
463→    },
464→    [features, votedIds, optimisticVotes, fetcher],
465→  );
466→
467→  const handleDelete = useCallback(
468→    (id: string) => {
469→      pendingIntentRef.current = "delete";
470→      pendingDeleteIdRef.current = id;
471→      setPendingDeleteId(id);
472→
473→      const fd = new FormData();
474→      fd.set("intent", "delete");
475→      fd.set("id", id);
476→      fetcher.submit(fd, { method: "POST" });
477→    },
478→    [fetcher],
479→  );
480→
481→  const handleSubmitFeature = useCallback(() => {
482→    if (!newTitle.trim() || !newDescription.trim()) {
483→      setModalError("Title and description are required.");
484→      return;
485→    }
486→    setModalError(null);
487→    pendingIntentRef.current = "submit";
488→    setIsSubmitting(true);
489→
490→    const fd = new FormData();
491→    fd.set("intent", "submit");
492→    fd.set("title", newTitle.trim());
493→    fd.set("description", newDescription.trim());
494→    fd.set("category", newCategory);
495→    fetcher.submit(fd, { method: "POST" });
496→  }, [newTitle, newDescription, newCategory, fetcher]);
497→
498→  const handleToggleExpand = useCallback((id: string) => {
499→    setExpandedIds((prev) => {
500→      const next = new Set(prev);
501→      if (next.has(id)) next.delete(id);
502→      else next.add(id);
503→      return next;
504→    });
505→  }, []);
506→
507→  const handleCloseModal = useCallback(() => {
508→    setModalOpen(false);
509→    setNewTitle("");
510→    setNewDescription("");
511→    setNewCategory("General");
512→    setModalError(null);
513→  }, []);
514→
515→  // ------------------------------------------------------------------
516→  // Tabs config
517→  // ------------------------------------------------------------------
518→  const tabs = [
519→    { id: "all", content: `All (${stats.total})` },
520→    { id: "under_review", content: `Under Review (${stats.under_review})` },
521→    { id: "planned", content: `Planned (${stats.planned})` },
522→    { id: "in_progress", content: `In Progress (${stats.in_progress})` },
523→    { id: "done", content: `Done (${stats.done})` },
524→  ];
525→
526→  // ------------------------------------------------------------------
527→  // Render
528→  // ------------------------------------------------------------------
529→  return (
530→    <Page
531→      title="Feature Requests"
532→      subtitle="Vote on features or suggest new ones. We review every request and ship based on community votes."
533→      backAction={{ onAction: () => navigate("/app") }}
534→      primaryAction={{
535→        content: "Suggest a Feature",
536→        icon: PlusIcon,
537→        onAction: () => setModalOpen(true),
538→      }}
539→    >
540→      <Box paddingBlockEnd="1600">
541→        <Layout>
542→
543→          {/* ---- Stats Bar ---- */}
544→          <Layout.Section>
545→            <InlineGrid columns={{ xs: 2, sm: 2, md: 5 }} gap="400">
546→              <Box
547→                padding="400"
548→                background="bg-surface"
549→                borderWidth="025"
550→                borderColor="border"
551→                borderRadius="200"
552→              >
553→                <BlockStack gap="100">
554→                  <Text as="p" tone="subdued" variant="bodySm">
555→                    Total Requests
556→                  </Text>
557→                  <Text as="p" variant="headingXl" fontWeight="bold">
558→                    {stats.total}
559→                  </Text>
560→                </BlockStack>
561→              </Box>
562→              <Box
563→                padding="400"
564→                background="bg-surface-warning"
565→                borderWidth="025"
566→                borderColor="border-warning"
567→                borderRadius="200"
568→              >
569→                <BlockStack gap="100">
570→                  <Text as="p" tone="caution" variant="bodySm">
571→                    Under Review
572→                  </Text>
573→                  <Text
574→                    as="p"
575→                    variant="headingXl"
576→                    fontWeight="bold"
577→                    tone="caution"
578→                  >
579→                    {stats.under_review}
580→                  </Text>
581→                </BlockStack>
582→              </Box>
583→              <Box
584→                padding="400"
585→                background="bg-surface-info"
586→                borderWidth="025"
587→                borderColor="border-info"
588→                borderRadius="200"
589→              >
590→                <BlockStack gap="100">
591→                  <Text as="p" tone="subdued" variant="bodySm">
592→                    Planned
593→                  </Text>
594→                  <Text as="p" variant="headingXl" fontWeight="bold">
595→                    {stats.planned}
596→                  </Text>
597→                </BlockStack>
598→              </Box>
599→              <Box
600→                padding="400"
601→                background="bg-surface"
602→                borderWidth="025"
603→                borderColor="border"
604→                borderRadius="200"
605→              >
606→                <BlockStack gap="100">
607→                  <Text as="p" tone="subdued" variant="bodySm">
608→                    In Progress
609→                  </Text>
610→                  <Text as="p" variant="headingXl" fontWeight="bold">
611→                    {stats.in_progress}
612→                  </Text>
613→                </BlockStack>
614→              </Box>
615→              <Box
616→                padding="400"
617→                background="bg-surface-success"
618→                borderWidth="025"
619→                borderColor="border-success"
620→                borderRadius="200"
621→              >
622→                <BlockStack gap="100">
623→                  <Text as="p" tone="success" variant="bodySm">
624→                    Done / Shipped
625→                  </Text>
626→                  <Text
627→                    as="p"
628→                    variant="headingXl"
629→                    fontWeight="bold"
630→                    tone="success"
631→                  >
632→                    {stats.done}
633→                  </Text>
634→                </BlockStack>
635→              </Box>
636→            </InlineGrid>
637→          </Layout.Section>
638→
639→          {/* ---- Filter Tabs + Sort + List ---- */}
640→          <Layout.Section>
641→            <Card padding="0">
642→              {/* Tabs */}
643→              <Tabs
644→                tabs={tabs}
645→                selected={selectedTab}
646→                onSelect={handleTabChange}
647→              />
648→              <Divider />
649→
650→              {/* Sort bar */}
651→              <Box padding="400">
652→                <InlineStack align="end">
653→                  <Box minWidth="180px">
654→                    <Select
655→                      label="Sort by"
656→                      labelInline
657→                      options={SORT_OPTIONS}
658→                      value={sortValue}
659→                      onChange={handleSortChange}
660→                    />
661→                  </Box>
662→                </InlineStack>
663→              </Box>
664→              <Divider />
665→
666→              {/* Feature list */}
667→              {filteredFeatures.length === 0 ? (
668→                <EmptyState
669→                  heading="No feature requests yet"
670→                  image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
671→                  action={{
672→                    content: "Suggest a Feature",
673→                    onAction: () => setModalOpen(true),
674→                  }}
675→                >
676→                  <Text as="p">
677→                    {tabFilter === "all"
678→                      ? "Be the first to suggest a feature. We review every request and ship based on community votes."
679→                      : "No feature requests with this status yet."}
680→                  </Text>
681→                </EmptyState>
682→              ) : (
683→                <BlockStack gap="0">
684→                  {paginatedFeatures.map((feature, index) => {
685→                    const isVoted = votedIds.has(feature.id);
686→                    const isOwner = feature.shop === shop;
687→                    const isExpanded = expandedIds.has(feature.id);
688→                    const needsTruncation = feature.description.length > 160;
689→                    const displayDescription = isExpanded
690→                      ? feature.description
691→                      : truncateText(feature.description, 160);
692→
693→                    return (
694→                      <Box key={feature.id}>
695→                        {index > 0 && <Divider />}
696→                        <Box padding="400">
697→                          <InlineStack
698→                            gap="400"
699→                            align="start"
700→                            blockAlign="start"
701→                            wrap={false}
702→                          >
703→                            {/* Vote button */}
704→                            <Box minWidth="56px">
705→                              <BlockStack gap="050" inlineAlign="center">
706→                                <Button
707→                                  variant={isVoted ? "primary" : "secondary"}
708→                                  size="slim"
709→                                  icon={ChevronUpIcon}
710→                                  onClick={() => handleVote(feature.id)}
711→                                  loading={
712→                                    pendingVoteId === feature.id &&
713→                                    fetcher.state !== "idle"
714→                                  }
715→                                  accessibilityLabel={
716→                                    isVoted
717→                                      ? "Remove vote"
718→                                      : "Vote for this feature"
719→                                  }
720→                                />
721→                                <Text
722→                                  as="p"
723→                                  variant="headingSm"
724→                                  fontWeight="bold"
725→                                  alignment="center"
726→                                  tone={isVoted ? "success" : undefined}
727→                                >
728→                                  {feature.votesCount}
729→                                </Text>
730→                              </BlockStack>
731→                            </Box>
732→
733→                            {/* Content */}
734→                            <Box width="100%">
735→                              <BlockStack gap="200">
736→                                <InlineStack
737→                                  align="space-between"
738→                                  blockAlign="start"
739→                                  wrap
740→                                >
741→                                  <Text
742→                                    as="p"
743→                                    variant="bodyMd"
744→                                    fontWeight="semibold"
745→                                  >
746→                                    {feature.title}
747→                                  </Text>
748→                                  <InlineStack
749→                                    gap="200"
750→                                    blockAlign="center"
751→                                    wrap
752→                                  >
753→                                    <Badge
754→                                      tone={STATUS_TONES[feature.status]}
755→                                    >
756→                                      {STATUS_LABELS[feature.status] ??
757→                                        feature.status}
758→                                    </Badge>
759→                                    <Badge>{feature.category}</Badge>
760→                                  </InlineStack>
761→                                </InlineStack>
762→
763→                                <Text as="p" tone="subdued" variant="bodySm">
764→                                  {displayDescription}
765→                                  {needsTruncation && (
766→                                    <>
767→                                      {" "}
768→                                      <Button
769→                                        variant="plain"
770→                                        size="slim"
771→                                        onClick={() =>
772→                                          handleToggleExpand(feature.id)
773→                                        }
774→                                      >
775→                                        {isExpanded
776→                                          ? "Show less"
777→                                          : "View details"}
778→                                      </Button>
779→                                    </>
780→                                  )}
781→                                </Text>
782→
783→                                <InlineStack
784→                                  gap="400"
785→                                  blockAlign="center"
786→                                  wrap
787→                                >
788→                                  <Text
789→                                    as="p"
790→                                    tone="subdued"
791→                                    variant="bodySm"
792→                                  >
793→                                    Submitted {formatDate(feature.createdAt)}
794→                                  </Text>
795→                                  {isOwner && (
796→                                    <Button
797→                                      variant="plain"
798→                                      tone="critical"
799→                                      size="slim"
800→                                      icon={DeleteIcon}
801→                                      onClick={() =>
802→                                        handleDelete(feature.id)
803→                                      }
804→                                      loading={
805→                                        pendingDeleteId === feature.id &&
806→                                        fetcher.state !== "idle"
807→                                      }
808→                                      accessibilityLabel="Delete feature request"
809→                                    >
810→                                      Delete
811→                                    </Button>
812→                                  )}
813→                                </InlineStack>
814→                              </BlockStack>
815→                            </Box>
816→                          </InlineStack>
817→                        </Box>
818→                      </Box>
819→                    );
820→                  })}
821→                </BlockStack>
822→              )}
823→
824→              {/* Pagination */}
825→              {totalPages > 1 && (
826→                <>
827→                  <Divider />
828→                  <Box padding="400">
829→                    <InlineStack align="center" gap="400" blockAlign="center">
830→                      <Button
831→                        disabled={currentPage <= 1}
832→                        onClick={() =>
833→                          setCurrentPage((p) => Math.max(1, p - 1))
834→                        }
835→                      >
836→                        Previous
837→                      </Button>
838→                      <Text as="p" tone="subdued" variant="bodySm">
839→                        Page {currentPage} of {totalPages} (
840→                        {filteredFeatures.length} requests)
841→                      </Text>
842→                      <Button
843→                        disabled={currentPage >= totalPages}
844→                        onClick={() =>
845→                          setCurrentPage((p) => Math.min(totalPages, p + 1))
846→                        }
847→                      >
848→                        Next
849→                      </Button>
850→                    </InlineStack>
851→                  </Box>
852→                </>
853→              )}
854→            </Card>
855→          </Layout.Section>
856→
857→        </Layout>
858→      </Box>
859→
860→      {/* ---- Suggest a Feature Modal ---- */}
861→      <Modal
862→        open={modalOpen}
863→        onClose={handleCloseModal}
864→        title="Suggest a Feature"
865→        primaryAction={{
866→          content: "Submit Request",
867→          onAction: handleSubmitFeature,
868→          loading: isSubmitting,
869→        }}
870→        secondaryActions={[{ content: "Cancel", onAction: handleCloseModal }]}
871→      >
872→        <Modal.Section>
873→          <BlockStack gap="400">
874→            {modalError && (
875→              <Banner tone="critical" onDismiss={() => setModalError(null)}>
876→                {modalError}
877→              </Banner>
878→            )}
879→            <TextField
880→              label="Title"
881→              value={newTitle}
882→              onChange={setNewTitle}
883→              placeholder="e.g. Export ZIP codes to CSV"
884→              autoComplete="off"
885→              maxLength={150}
886→              showCharacterCount
887→              helpText="Keep it short and descriptive."
888→            />
889→            <TextField
890→              label="Description"
891→              value={newDescription}
892→              onChange={setNewDescription}
893→              placeholder="Describe the feature and why it would be valuable..."
894→              autoComplete="off"
895→              multiline={4}
896→              helpText="The more context you provide, the better we can understand your needs."
897→            />
898→            <Select
899→              label="Category"
900→              options={CATEGORY_OPTIONS}
901→              value={newCategory}
902→              onChange={setNewCategory}
903→              helpText="Choose the category that best fits your request."
904→            />
905→          </BlockStack>
906→        </Modal.Section>
907→      </Modal>
908→    </Page>
909→  );
910→}
